cd /tmp && cat > /tmp/check-bot.mjs <<'EOF'
import { decideWhatsApp as d } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev1-haiku/work/ours-g5-3/bot.mjs';
const T = "1767272400"; // 2026-01-01T11:00:00Z
const at = (ms) => new Date(Date.parse("2026-01-01T11:00:00Z") + ms);
const H = 3600e3;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T, ...over });
const cases = [
  ["text in window", { type: "text", contact: c() }, at(23*H + 59999), { allowed: true, reason: null }],
  ["text at exactly 24h", { type: "text", contact: c() }, at(24*H), { allowed: false, reason: "service_window_closed" }],
  ["text after 24h", { type: "text", contact: c() }, at(30*H), { allowed: false, reason: "service_window_closed" }],
  ["text never inbound", { type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: false, reason: "no_inbound_message" }],
  ["text bad timestamp", { type: "text", contact: c({ lastInboundTimestamp: "2026-01-01" }) }, at(0), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text numeric timestamp (not string)", { type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(0), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["template outside window", { type: "template", contact: c() }, at(100*H), { allowed: true, reason: null }],
  ["template never inbound", { type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: true, reason: null }],
  ["text not opted in", { type: "text", contact: c({ optedIn: false }) }, at(H), { allowed: false, reason: "not_opted_in" }],
  ["template not opted in", { type: "template", contact: c({ optedIn: false }) }, at(H), { allowed: false, reason: "not_opted_in" }],
  ["optedIn missing", { type: "template", contact: { lastInboundTimestamp: null } }, at(0), { allowed: false, reason: "not_opted_in" }],
  ["unknown type", { type: "image", contact: c() }, at(H), { allowed: false, reason: "unsupported_message_type" }],
  ["null message", null, at(0), { allowed: false, reason: "invalid_message" }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = d(msg, now);
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
try { d({ type: "text", contact: c() }, new Date("x")); console.log("FAIL invalid now did not throw"); fail++; }
catch (e) { console.log("PASS invalid now throws", e.name); }
console.log(fail ? `${fail} FAILED` : "all passed");
process.exit(fail ? 1 : 0);
EOF
node /tmp/check-bot.mjs; echo "exit=$?"; rm -f /tmp/check-bot.mjs

